insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$perkins-diesel-generator-10-200kva$q$,$q$Perkins Diesel Generator 10–200 kVA$q$,$q$مولد ديزل بيركنز 10–200 كيلو فولت أمبير$q$,10,200,$q$Perkins$q$,$q$diesel$q$,$q$Compact Perkins 400 and 1100 Series powered generator sets for villas, shops, telecom sites and light commercial standby. Low fuel consumption, wide parts availability across the GCC and fast delivery from our SAIF Zone warehouse.$q$,$q$مولدات بمحركات بيركنز من الفئة 400 و1100 للفلل والمحلات ومواقع الاتصالات والاستخدام التجاري الاحتياطي الخفيف. استهلاك وقود منخفض، قطع غيار متوفرة في كل دول الخليج، وتسليم سريع من مستودعنا في المنطقة الحرة بالشارقة.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"10 – 200 kVA (prime / standby)","value_ar":"10 – 200 ك.ف.أ (أساسي / احتياطي)"},{"label_en":"Engine","label_ar":"المحرك","value_en":"Perkins 400 / 1100 Series, water-cooled","value_ar":"بيركنز الفئة 400 / 1100، تبريد بالماء"},{"label_en":"Alternator","label_ar":"المولّد (الدينامو)","value_en":"Brushless, H-class insulation","value_ar":"بدون فرش، عزل فئة H"},{"label_en":"Output voltage","label_ar":"جهد الخرج","value_en":"400/230 V, 3-phase, 50 Hz (60 Hz on request)","value_ar":"400/230 فولت، 3 أطوار، 50 هرتز (60 هرتز عند الطلب)"},{"label_en":"Enclosure","label_ar":"الهيكل","value_en":"Open frame or sound-attenuated canopy","value_ar":"إطار مفتوح أو كابينة عازلة للصوت"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Deep Sea / ComAp auto-start (AMF)","value_ar":"Deep Sea / ComAp تشغيل تلقائي (AMF)"},{"label_en":"Ambient rating","label_ar":"ظروف التشغيل","value_en":"Configured for 50 °C GCC ambient","value_ar":"مهيأ لحرارة الخليج حتى 50 °م"},{"label_en":"Fuel tank","label_ar":"خزان الوقود","value_en":"8–12 hour base tank","value_ar":"خزان قاعدي يكفي 8–12 ساعة"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/perkins-diesel-generator-4u.webp$q$,$q$/images/products/generator-canopy.svg$q$,$q$/images/products/generator-open.svg$q$]::text[],10,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
