insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$generator$q$,$q$hybrid-battery-generator-20-200kva$q$,$q$Hybrid Generator + Battery System 20–200 kVA$q$,$q$نظام مولد هجين مع بطاريات 20–200 كيلو فولت أمبير$q$,20,200,null,$q$hybrid$q$,$q$Diesel generator paired with a lithium battery bank and smart controller. The engine only runs when needed, cutting fuel use and maintenance on low- or variable-load sites.$q$,$q$مولد ديزل مقترن بمجموعة بطاريات ليثيوم ووحدة تحكم ذكية، يعمل المحرك فقط عند الحاجة فيقلل استهلاك الوقود والصيانة في المواقع ذات الأحمال المنخفضة أو المتغيرة.$q$,$q$[{"label_en":"Power range","label_ar":"نطاق القدرة","value_en":"20 – 200 kVA","value_ar":"20 – 200 ك.ف.أ"},{"label_en":"Storage","label_ar":"التخزين","value_en":"LiFePO4 battery bank, sized per site","value_ar":"بطاريات ليثيوم فوسفات الحديد حسب الموقع"},{"label_en":"Typical fuel saving","label_ar":"التوفير المعتاد في الوقود","value_en":"Up to 50% on low-load sites","value_ar":"حتى 50% في المواقع منخفضة الحمل"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/generator-canopy.svg$q$]::text[],90,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
