insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$ats_panel$q$,$q$ats-panel-63a-400a$q$,$q$Automatic Transfer Switch Panel 63–400 A$q$,$q$لوحة تحويل أوتوماتيكي ATS من 63 إلى 400 أمبير$q$,10,275,null,null,$q$Wall- or floor-mounted ATS panels that switch your load from mains to generator in seconds when power fails — and back again when it returns. Motorised changeover or contactor based, 3- or 4-pole.$q$,$q$لوحات ATS جدارية أو أرضية تنقل الحمل من الكهرباء العامة إلى المولد خلال ثوانٍ عند انقطاع التيار، وتعيده تلقائياً عند عودته. بمفتاح تحويل مُحرّك أو كونتاكتور، 3 أو 4 أقطاب.$q$,$q$[{"label_en":"Current rating","label_ar":"التيار المقنن","value_en":"63 – 400 A","value_ar":"63 – 400 أمبير"},{"label_en":"Poles","label_ar":"الأقطاب","value_en":"3P or 4P (switched neutral)","value_ar":"3 أو 4 أقطاب (فصل التعادل)"},{"label_en":"Controller","label_ar":"وحدة التحكم","value_en":"Auto mains-failure with adjustable timers","value_ar":"كشف انقطاع تلقائي مع مؤقتات قابلة للضبط"},{"label_en":"Enclosure","label_ar":"الغلاف","value_en":"IP54 powder-coated steel (IP65 option)","value_ar":"حديد مطلي IP54 (خيار IP65)"},{"label_en":"Testing","label_ar":"الاختبار","value_en":"Factory function-tested before dispatch","value_ar":"مختبرة وظيفياً قبل الشحن"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/ats-panel.svg$q$]::text[],110,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$ats_panel$q$,$q$ats-panel-630a-4000a$q$,$q$High-Current ATS Panel 630–4000 A$q$,$q$لوحة ATS للتيارات العالية من 630 إلى 4000 أمبير$q$,276,2770,null,null,$q$Floor-standing ATS and ACB-based changeover panels for industrial plants, hospitals and towers — with metering, bypass and multi-source (mains/generator/generator) logic.$q$,$q$لوحات تحويل أرضية بقواطع ACB للمصانع والمستشفيات والأبراج، مع قياس رقمي وخيار تجاوز (Bypass) ومنطق تحويل بين عدة مصادر (كهرباء/مولد/مولد).$q$,$q$[{"label_en":"Current rating","label_ar":"التيار المقنن","value_en":"630 – 4000 A","value_ar":"630 – 4000 أمبير"},{"label_en":"Switching device","label_ar":"جهاز التحويل","value_en":"Motorised ACB pair or open-transition ATS","value_ar":"زوج قواطع ACB مُحرّكة أو ATS انتقال مفتوح"},{"label_en":"Metering","label_ar":"القياس","value_en":"Multifunction meter, Modbus","value_ar":"عداد متعدد الوظائف، Modbus"},{"label_en":"Form of separation","label_ar":"نوع الفصل الداخلي","value_en":"Up to Form 4b","value_ar":"حتى Form 4b"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/ats-panel.svg$q$,$q$/images/products/switchgear.svg$q$]::text[],120,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
