insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$switchgear$q$,$q$low-voltage-switchgear-panel$q$,$q$Low Voltage Switchgear Panel up to 6300 A$q$,$q$لوحة مفاتيح جهد منخفض حتى 6300 أمبير$q$,null,null,null,null,$q$Main LV switchboards built around ACB incomers and MCCB feeders for buildings, plants and infrastructure — configured to your single-line diagram and local authority requirements.$q$,$q$لوحات توزيع رئيسية للجهد المنخفض بقواطع ACB للمداخل وMCCB للمخارج، للمباني والمصانع والبنية التحتية، وتُجهّز وفق المخطط أحادي الخط ومتطلبات هيئة الكهرباء المحلية.$q$,$q$[{"label_en":"Rated current","label_ar":"التيار المقنن","value_en":"Up to 6300 A","value_ar":"حتى 6300 أمبير"},{"label_en":"Short-circuit rating","label_ar":"تحمّل القصر","value_en":"Up to 100 kA / 1 s (design dependent)","value_ar":"حتى 100 ك.أ / 1 ث (حسب التصميم)"},{"label_en":"Standard","label_ar":"المعيار","value_en":"Designed to IEC 61439","value_ar":"مصممة وفق IEC 61439"},{"label_en":"Form of separation","label_ar":"نوع الفصل الداخلي","value_en":"Form 2 to Form 4b","value_ar":"من Form 2 إلى Form 4b"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/switchgear.svg$q$]::text[],130,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
