insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$mdb$q$,$q$main-distribution-board-mdb$q$,$q$Main Distribution Board (MDB) up to 4000 A$q$,$q$لوحة التوزيع الرئيسية MDB حتى 4000 أمبير$q$,null,null,null,null,$q$MDBs, SMDBs and DBs for villas, towers, warehouses and factories — busbar-based, fully labelled and supplied with test certificates ready for utility inspection.$q$,$q$لوحات توزيع رئيسية وفرعية للفلل والأبراج والمستودعات والمصانع، بقضبان نحاسية ومُعلّمة بالكامل ومع شهادات اختبار جاهزة لفحص هيئة الكهرباء.$q$,$q$[{"label_en":"Rated current","label_ar":"التيار المقنن","value_en":"100 – 4000 A","value_ar":"100 – 4000 أمبير"},{"label_en":"Busbar","label_ar":"القضبان","value_en":"Tinned copper, sized per design","value_ar":"نحاس مقصدر حسب التصميم"},{"label_en":"Types","label_ar":"الأنواع","value_en":"MDB, SMDB, DB, capacitor bank","value_ar":"MDB وSMDB وDB ولوحات مكثفات"},{"label_en":"Utility approval","label_ar":"اعتماد الهيئة","value_en":"Built to DEWA / SEWA / ADDC / SEC requirements on request","value_ar":"حسب متطلبات ديوا / سيوا / أدك / السعودية للكهرباء عند الطلب"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/mdb.svg$q$]::text[],150,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$sync_panel$q$,$q$generator-synchronizing-panel$q$,$q$Generator Synchronizing Panel$q$,$q$لوحة تزامن المولدات$q$,200,10000,null,null,$q$Run two or more generators in parallel as one power plant — load sharing, load-demand start/stop and mains synchronisation for redundancy and fuel efficiency.$q$,$q$تشغيل مولدين أو أكثر على التوازي كمحطة طاقة واحدة، مع توزيع الأحمال وتشغيل/إيقاف حسب الطلب والتزامن مع الشبكة لتحقيق الاعتمادية وتوفير الوقود.$q$,$q$[{"label_en":"Configuration","label_ar":"التكوين","value_en":"2 – 16 generators in parallel","value_ar":"من 2 إلى 16 مولداً على التوازي"},{"label_en":"Controllers","label_ar":"وحدات التحكم","value_en":"Deep Sea DSE8610 / ComAp InteliGen","value_ar":"Deep Sea DSE8610 / ComAp InteliGen"},{"label_en":"Functions","label_ar":"الوظائف","value_en":"Load sharing, load-demand, mains paralleling","value_ar":"توزيع الأحمال، التشغيل حسب الطلب، التوازي مع الشبكة"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/sync-panel.svg$q$]::text[],160,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$solar$q$,$q$solar-pv-panels$q$,$q$Solar PV Panels 450–700 W$q$,$q$ألواح شمسية كهروضوئية 450–700 واط$q$,null,null,null,$q$solar$q$,$q$Tier-1 monocrystalline PV modules for rooftops, farms, telecom sites and solar-hybrid gensets — supplied loose or as complete kits with inverters, mounting structures and cabling.$q$,$q$ألواح شمسية أحادية البلورة من الفئة الأولى للأسطح والمزارع ومحطات الاتصالات وأنظمة المولدات الهجينة، تُورَّد منفردة أو كحزمة كاملة مع المحولات (الإنفرتر) وهياكل التثبيت والكابلات.$q$,$q$[{"label_en":"Module power","label_ar":"قدرة اللوح","value_en":"450 – 700 Wp","value_ar":"450 – 700 واط ذروة"},{"label_en":"Cell technology","label_ar":"تقنية الخلايا","value_en":"Monocrystalline PERC / TOPCon, bifacial options","value_ar":"أحادية البلورة PERC / TOPCon مع خيارات ثنائية الوجه"},{"label_en":"Module efficiency","label_ar":"كفاءة اللوح","value_en":"Typically 21 – 23 %","value_ar":"عادةً 21 – 23%"},{"label_en":"System options","label_ar":"خيارات النظام","value_en":"On-grid, off-grid and hybrid with inverters & batteries","value_ar":"متصل بالشبكة أو مستقل أو هجين مع الإنفرتر والبطاريات"},{"label_en":"Mounting","label_ar":"التثبيت","value_en":"Rooftop, ground-mount and carport structures","value_ar":"هياكل للأسطح والأرض ومظلات السيارات"},{"label_en":"Climate","label_ar":"ظروف التشغيل","value_en":"Selected for high-temperature, dusty GCC sites","value_ar":"مختارة لمواقع الخليج عالية الحرارة والغبار"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/solar-pv.svg$q$]::text[],200,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$solar$q$,$q$solar-power-stations-parks$q$,$q$Solar Power Stations & Solar Parks$q$,$q$محطات ومزارع الطاقة الشمسية$q$,null,null,null,$q$solar$q$,$q$Design, supply, installation and commissioning of ground-mounted solar stations and parks — from farm and factory plants to utility-scale fields, integrated with generators and switchgear.$q$,$q$تصميم وتوريد وتركيب وتشغيل محطات ومزارع الطاقة الشمسية الأرضية، من محطات المزارع والمصانع حتى الحقول الكبيرة، مع دمجها بالمولدات ولوحات الكهرباء.$q$,$q$[{"label_en":"Plant size","label_ar":"حجم المحطة","value_en":"From 50 kWp to multi-MWp","value_ar":"من 50 كيلوواط ذروة حتى عدة ميغاواط"},{"label_en":"Scope","label_ar":"نطاق العمل","value_en":"Design, supply, installation, testing & commissioning","value_ar":"التصميم والتوريد والتركيب والاختبار والتشغيل"},{"label_en":"Configuration","label_ar":"التكوين","value_en":"On-grid, off-grid or solar-diesel hybrid","value_ar":"متصل بالشبكة أو مستقل أو هجين شمسي-ديزل"},{"label_en":"Integration","label_ar":"الربط","value_en":"LV / MV switchgear, ATS, sync with generators, BESS","value_ar":"لوحات جهد منخفض ومتوسط، ATS، تزامن مع المولدات، تخزين بالبطاريات"},{"label_en":"Monitoring","label_ar":"المراقبة","value_en":"Remote plant monitoring and reporting","value_ar":"مراقبة المحطة عن بُعد وتقارير الأداء"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/solar-station.svg$q$,$q$/images/products/solar-pv.svg$q$]::text[],210,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_