insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$solar$q$,$q$solar-light-tower$q$,$q$Solar Light Tower (LED)$q$,$q$برج إنارة شمسي (LED)$q$,null,null,null,$q$solar$q$,$q$Trailer-mounted LED light tower powered by solar panels and batteries — silent, zero fuel, ideal for construction sites, roads, events and security perimeters.$q$,$q$برج إنارة LED على مقطورة يعمل بالألواح الشمسية والبطاريات؛ صامت وبدون وقود، مثالي لمواقع الإنشاءات والطرق والفعاليات وأسوار الحماية.$q$,$q$[{"label_en":"Lighting","label_ar":"الإنارة","value_en":"4 × LED floodlights","value_ar":"4 كشافات LED"},{"label_en":"Mast","label_ar":"الصاري","value_en":"Telescopic, typically 7 – 9 m","value_ar":"تلسكوبي، عادةً 7 – 9 أمتار"},{"label_en":"Power","label_ar":"مصدر الطاقة","value_en":"Solar panels + lithium or gel battery bank","value_ar":"ألواح شمسية + بطاريات ليثيوم أو جل"},{"label_en":"Operation","label_ar":"التشغيل","value_en":"Dusk-to-dawn automatic, timer or manual","value_ar":"تلقائي من الغروب حتى الشروق، أو بمؤقت أو يدوي"},{"label_en":"Mobility","label_ar":"التنقل","value_en":"Towable trailer with outriggers","value_ar":"مقطورة قابلة للسحب مع دعامات تثبيت"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/solar-light-tower.svg$q$]::text[],220,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$solar$q$,$q$battery-energy-storage-bess$q$,$q$Battery Energy Storage Systems (BESS)$q$,$q$أنظمة تخزين الطاقة بالبطاريات (BESS)$q$,null,null,null,$q$hybrid$q$,$q$Lithium battery storage that stores solar energy, shaves peaks and lets generators run less — cabinet and containerised systems with hybrid inverters and energy management.$q$,$q$تخزين بالبطاريات الليثيوم يحفظ الطاقة الشمسية ويخفض أحمال الذروة ويقلل ساعات تشغيل المولدات، في خزائن أو حاويات مع إنفرتر هجين ونظام إدارة طاقة.$q$,$q$[{"label_en":"Capacity","label_ar":"السعة","value_en":"From 30 kWh cabinets to multi-MWh containers","value_ar":"من خزائن 30 كيلوواط ساعة حتى حاويات بعدة ميغاواط ساعة"},{"label_en":"Chemistry","label_ar":"نوع البطاريات","value_en":"Lithium iron phosphate (LFP)","value_ar":"ليثيوم فوسفات الحديد (LFP)"},{"label_en":"Functions","label_ar":"الوظائف","value_en":"Solar shifting, peak shaving, genset hybridisation, backup","value_ar":"نقل الطاقة الشمسية، خفض الذروة، التشغيل الهجين مع المولد، الطاقة الاحتياطية"},{"label_en":"Cooling","label_ar":"التبريد","value_en":"Air-conditioned enclosures for GCC ambient","value_ar":"أغلفة مكيفة لحرارة الخليج"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/bess.svg$q$]::text[],230,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort_order=excluded.sort_order,is_published=excluded.is_published;
insert into public.products (category,slug,name_en,name_ar,kva_min,kva_max,engine_brand,fuel_type,description_en,description_ar,specs,spec_sheet_url,images,sort_order,is_published) values ($q$accessories$q$,$q$generator-fuel-tanks$q$,$q$Generator Fuel Tanks — Base, Day & Bulk$q$,$q$خزانات وقود المولدات — قاعدية ويومية ورئيسية$q$,null,null,null,$q$diesel$q$,$q$Double-wall base tanks, day tanks and bulk storage tanks with fuel transfer systems, level gauges and alarms — sized for the run time your site needs.$q$,$q$خزانات قاعدية مزدوجة الجدار وخزانات يومية وخزانات تخزين رئيسية مع أنظمة نقل الوقود ومؤشرات المنسوب والإنذارات، بأحجام تناسب مدة التشغيل المطلوبة لموقعك.$q$,$q$[{"label_en":"Types","label_ar":"الأنواع","value_en":"Sub-base (belly), day tanks, above-ground bulk tanks","value_ar":"خزانات قاعدية، خزانات يومية، خزانات رئيسية فوق الأرض"},{"label_en":"Capacity","label_ar":"السعة","value_en":"Typically 500 – 50,000 litres","value_ar":"عادةً 500 – 50,000 لتر"},{"label_en":"Construction","label_ar":"التصنيع","value_en":"Single or double wall steel, painted / galvanised","value_ar":"حديد بجدار مفرد أو مزدوج، مطلي أو مجلفن"},{"label_en":"Accessories","label_ar":"الملحقات","value_en":"Transfer pumps, level gauge, low/high alarms, leak detection","value_ar":"مضخات نقل، مؤشر منسوب، إنذارات انخفاض وارتفاع، كشف تسرب"},{"label_en":"Autonomy","label_ar":"مدة التشغيل","value_en":"Sized for 8 h to several days of run time","value_ar":"بأحجام تكفي من 8 ساعات حتى عدة أيام تشغيل"}]$q$::jsonb,$q$/datasheets/4u-datasheet-placeholder.pdf$q$,array[$q$/images/products/fuel-tank.svg$q$]::text[],300,true) on conflict (slug) do update set category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,kva_min=excluded.kva_min,kva_max=excluded.kva_max,engine_brand=excluded.engine_brand,fuel_type=excluded.fuel_type,description_en=excluded.description_en,description_ar=excluded.description_ar,specs=excluded.specs,spec_sheet_url=excluded.spec_sheet_url,images=excluded.images,sort